 const sourceCredits=Number(g.credits||0),sourceTP=Number(g.tradePoints||0),sourceXP=fighters(g).reduce((sum,f)=>sum+Number(f.xp||0),0),owned=new Set(ownedTactics(g).map(row=>row.id)),uniqueTactics=(R().tactics||[]).filter(row=>row.source_verified&&row.d66_min&&String(row.edition_slug||row.edition).toLowerCase()==='n26'&&!owned.has(row.id)).length;
