    if(row.action==='bionics')push(campaign,'postCycleActions',{id:'batch-preview-target-'+row.index,cycle:cycle(campaign),gangId:gang.id,gangKey:gangKey(campaign,gang),fighterId:target.id,action:'bionics-target',slot:'regular'});
    push(campaign,'medicalEscorts',treatment);summary.treatments++;summary.treatmentCost+=Math.max(0,(row.action==='medical'?30:50*injuryIds.length)-result.discount);
