 const task=(async()=>{let changed=false;for(const g of participants(c)){if((window.AccountParity?.account?.id||'')!==actor||A()?.phase(c)!=='Downtime'||occurrence(c)!==occ)return changed;if(list(c,'downtimeReceipts').some(r=>belongs(c,g,r)&&r.occurrence===occ))continue;await A().apply(c,{key:`auto-${occ}:${gangKey(c,g)}`,label:'Automatic Downtime allowance',gangIds:[g.id],mutate:draft=>{const dc=draft.campaign,dg=draft.gangs.find(row=>row.id===g.id);if(!dg||A()?.phase(dc)!=='Downtime'||occurrence(dc)!==occ)throw Error(T('The Downtime changed. Refresh the campaign.','다운타임이 변경되었습니다. 캠페인을 새로고침하세요.'));if(list(dc,'downtimeReceipts').some(r=>belongs(dc,dg,r)&&r.occurrence===occ))return;const existing=(dg.campaignDowntimeAllowances||[]).find(a=>a.campaignId===cid(dc)&&a.occurrence===occ);if(existing)push(dc,'downtimeReceipts',{gangId:dg.id,gangKey:gangKey(dc,dg),occurrence:occ,cycle:cycle(dc),allowanceId:existing.id,at:at(),automatic:true});else grantDowntime(dc,dg);}});changed=true;}return changed;})();automaticEconomyTasks.set(taskKey,task);try{return await task;}finally{if(automaticEconomyTasks.get(taskKey)===task)automaticEconomyTasks.delete(taskKey);}
